function summary=validate_hcp_stage3_naturalistic(workspace)
%VALIDATE_HCP_STAGE3_NATURALISTIC 同音频故事真实对齐，训练Story34/外测Story7。
if nargin<1,workspace=fileparts(fileparts(fileparts(mfilename('fullpath'))));end
addpath(fullfile(workspace,'function_toolkit'));setup_function('D:/matlab/atoolbox/spm12');out=fullfile(workspace,'derivatives','function_stage3_naturalistic_20261017');if isfolder(out),error('cog:Exists','Preserve successful output');end;mkdir(out);subjects=["100206";"100307";"100408"];request=struct('roiFile',fullfile(workspace,'derivatives','function_stage1_real_20261016','prepared','100206','engineering_rois.nii'),'records',{{}});epochs=cell(3,2);media=strings(3,2);durations=zeros(3,2);
for k=1:3
    root=fullfile('D:/IBM',subjects(k)+"_extracted",subjects(k)+"_Task3TRecommended",subjects(k),'MNINonLinear','Results','tfMRI_LANGUAGE_LR');bold=fullfile(root,'tfMRI_LANGUAGE_LR_hp0_clean_rclean_tclean.nii.gz');request.records{end+1}=struct('subject',subjects(k),'bold',bold,'outputFile',fullfile(out,subjects(k)+"_full_roi.mat"));
    ep=fullfile('D:/IBM',subjects(k)+"_extracted",subjects(k)+"_3T_tfMRI_LANGUAGE_unproc",subjects(k),'unprocessed','3T','tfMRI_LANGUAGE_LR','LINKED_DATA','EPRIME');files=dir(fullfile(ep,'*_TAB.txt'));if numel(files)~=1,error('cog:ExampleStory','One raw story table expected');end;raw=cog.read_tsv(fullfile(ep,files(1).name));rows=find(str2double(raw.('PresentStoryFile.OnsetTime'))>0);sync=readmatrix(fullfile(ep,'EVs','Sync.txt'),'FileType','text');ev=readmatrix(fullfile(ep,'EVs','present_story.txt'),'FileType','text');onset=str2double(raw.('PresentStoryFile.OnsetTime')(rows))/1000-sync(1);if numel(rows)~=size(ev,1)||any(abs(onset-ev(:,1))>.02),error('cog:ExampleStory','Story EV/raw onset identities could not be verified');end
    story=str2double(raw.StoryNumber(rows));for j=1:2,wanted=[34 7];i=find(story==wanted(j));if numel(i)~=1,error('cog:ExampleStory','Explicit common story missing/duplicated');end;epochs{k,j}=ev(i,1:2);media(k,j)=raw.StoryFile(rows(i));durations(k,j)=ev(i,2);end
end
if any(media~=media(1,:),'all'),error('cog:ExampleStory','Audio file identities differ across subjects');end
file=fullfile(out,'roi_request.json');cog.write_json(file,request);cog.python_process('D:/matlab/atoolbox/function_glhmm_env/Scripts/python.exe',fullfile(workspace,'function_toolkit','examples','hcp_naturalistic_roi.py'),{file},fullfile(out,'roi_preparation.log'),300);
step=.72;lag=4.32;trainTime=(0:floor((min(durations(:,1))-step)/step))'*step;testTime=(0:floor((min(durations(:,2))-step)/step))'*step;series=cell(3,1);testSeries=series;ids=series;queryTimes=cell(3,2);base=function_config;base.clean.bandHz=[];
for k=1:3
    s=load(request.records{k}.outputFile);[roi,processing]=cog.clean_timeseries(s.roi,s.trSeconds,[],base.clean);times=(0:size(roi,1)-1)'*s.trSeconds;queryTimes{k,1}=epochs{k,1}(1)+lag+trainTime;queryTimes{k,2}=epochs{k,2}(1)+lag+testTime;series{k}=interp1(times,roi,queryTimes{k,1},'linear');testSeries{k}=interp1(times,roi,queryTimes{k,2},'linear');ids{k}="engineering_roi_"+string(s.roiLabels(:)); %#ok<NASGU>
end
data=struct('series',{series},'subjectIds',subjects,'featureIds',{ids},'timeSeconds',trainTime,'stimulusId','LANGUAGE_LR_Story34','alignmentNote','Same verified StoryFile in all three EPRIME tables; published present_story/raw onset within20ms, interpolation on common relative time grid after fixed4.32s engineering hemodynamic offset. Released clean volume ROI means; additional intercept/trend projection only.', ...
    'testSeries',{testSeries},'testSubjectIds',subjects,'testFeatureIds',{ids},'testTimeSeconds',testTime,'testStimulusId','LANGUAGE_LR_Story7','testAlignmentNote','Separate nonoverlapping common audio story, same ROI identities; frozen SRM mapping from Story34 only.','mediaFiles',media,'sourceQueryTimes',{queryTimes},'hemodynamicOffsetSeconds',lag);input=fullfile(out,'aligned_data.mat');save(input,'data');c=naturalistic_config;c.dataFile=input;c.outputRoot=fullfile(out,'results');c.execute=true;c.srm.nFeatures=2;c.isc.nSurrogates=19;c.events.nEvents=2;c.events.maxIterations=40;summary=run_naturalistic(c);summary.scope='Three shared Story34 audio epochs, six fixed engineering ROIs, common relative interpolation grid/fixed4.32s offset; Story7 held-out for frozen deterministic SRM maps. 19 circular-shift ISC/ISFC surrogates and two ordered events. Short-epoch engineering test only, not full-movie/narrative/event-boundary/population inference.';cog.write_json(fullfile(out,'VALIDATION.json'),summary);
end
